<section x-show="daily" class="overflow-hidden rounded-2xl border border-slate-200 bg-white">
    <div class="flex flex-wrap items-center justify-between gap-3 p-5"><div><h2 class="text-sm font-bold text-slate-900">Pilih hari yang ingin direvisi</h2><p class="mt-1 text-xs text-slate-500">Tanggal/bulan · jam kerja tim. Tanda khusus berarti ada revisi tersimpan.</p></div><button type="button" @click="openDate(today)" x-show="today>=period.startDate&&today<=period.endDate" class="min-h-[44px] rounded-xl border border-slate-200 px-3 text-sm">Hari ini</button></div>
    <div class="grid grid-cols-7 bg-slate-50"><template x-for="name in ['Sen','Sel','Rab','Kam','Jum','Sab','Min']" :key="name"><div class="py-3 text-center text-xs font-semibold text-slate-500" x-text="name"></div></template></div>
    <div class="grid grid-cols-7"><template x-for="cell in calendarCells" :key="cell.key"><div class="min-w-0 border-r border-t border-slate-100"><template x-if="cell.date"><button type="button" @click="openDate(cell.date)" :disabled="saving||loading" :aria-pressed="selectedDate===cell.date" :aria-label="dateLabel(cell.date)+', '+number(cell.hours)+' jam kerja'+(cell.custom?', revisi khusus':'')+(cell.absence?', ada izin atau sakit':'')" :class="selectedDate===cell.date?'bg-brand-50 ring-2 ring-inset ring-brand-500':'hover:bg-slate-50'" class="min-h-[104px] w-full p-1.5 text-left sm:p-3"><span class="inline-block rounded-lg px-1.5 py-1 text-xs font-bold sm:text-sm" :class="cell.date===today?'bg-brand-700 text-white':'text-slate-800'" x-text="cell.day+'/'+cell.month"></span><span class="mt-2 block text-[10px] text-slate-500 sm:text-xs" x-text="cell.hours?number(cell.hours)+' jam':'Libur'"></span><span x-show="cell.custom" class="mt-1 block text-[10px] font-semibold text-indigo-700">Khusus</span><span x-show="cell.absence" class="mt-1 block text-[10px] font-semibold text-amber-800" x-text="cell.absence+' izin/sakit'"></span></button></template></div></template></div>
</section>
